INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Zeigt ifconfig nur IPv6-Adressen an?', 2, '[{"text": "Nein", "correct": true, "because": "Auch IPv4 und Schnittstellen"}, {"text": "Ja", "correct": false, "because": "Nicht auf IPv6 beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information gibt ifconfig über Schnittstellen?', 3, '[{"text": "Link-Local-Adresse", "correct": true, "because": "IPv6-Standard"}, {"text": "Bandbreitenlimit", "correct": false, "because": "Nicht enthalten"}, {"text": "Latenzzeit", "correct": false, "because": "Ping-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Details liefert ifconfig?', 5, '[{"text": "Schnittstellenname", "correct": true, "because": "z. B. eth0"}, {"text": "IPv6-Adresse mit Scope-ID", "correct": true, "because": "z. B. FE80::%eth0"}, {"text": "Paketverlust", "correct": false, "because": "Diagnose-Tool"}, {"text": "DNS-Server", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ifconfig zeigt die Scope-ID. b) Es ist auch für Windows.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Windows nutzt ipconfig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei ifconfig für IPv6?', 4, '[{"text": "Scope-ID", "correct": false, "because": "Wichtig für Link-Local"}, {"text": "Schnittstellenname", "correct": false, "because": "Identifiziert Interface"}, {"text": "CPU-Takt", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ifconfig MAC-Adressen anzeigt?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Schnittstelleninfo"}, {"text": "Nein", "correct": false, "because": "Standardausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse sehe ich mit ifconfig?', 3, '[{"text": "FE80::%eth0", "correct": true, "because": "Link-Local mit Scope"}, {"text": "FF02::1", "correct": false, "because": "Multicast, nicht eigener"}, {"text": "2001:db8::1", "correct": false, "because": "Globale Unicast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen bietet ifconfig über Netzwerke?', 5, '[{"text": "IPv6-Adresse", "correct": true, "because": "Aktuelle Adresse"}, {"text": "Schnittstellenstatus", "correct": true, "because": "Up oder Down"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}, {"text": "Firewall-Regeln", "correct": false, "because": "Anderes Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ifconfig zeigt Scope-ID an. b) Es ist veraltet. Stimmt das?', 3, '[{"text": "Beides stimmt", "correct": true, "because": "ip ersetzt ifconfig oft"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ifconfig?', 4, '[{"text": "Schnittstellenname", "correct": false, "because": "Identifiziert Interface"}, {"text": "IPv6-Adresse", "correct": false, "because": "Kerninformation"}, {"text": "Webserver-Port", "correct": true, "because": "Nicht Netzwerk-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ifconfig globale IPv6-Adressen?', 2, '[{"text": "Ja", "correct": true, "because": "Falls konfiguriert"}, {"text": "Nein", "correct": false, "because": "Abhängig von Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Scope-ID bei ifconfig?', 4, '[{"text": "Identifiziert Interface", "correct": true, "because": "z. B. %eth0"}, {"text": "Misst Latenz", "correct": false, "because": "Ping-Funktion"}, {"text": "Weist IPs zu", "correct": false, "because": "DHCP-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ifconfig nur für IPv4 ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Unterstützt auch IPv6"}, {"text": "Ja", "correct": false, "because": "Missverständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei ifconfig?', 3, '[{"text": "Schnittstellenname", "correct": true, "because": "Definiert Interface"}, {"text": "Paketgröße", "correct": false, "because": "Diagnose-relevant"}, {"text": "DNS-Eintrag", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ifconfig zeigt Link-Local-Adressen. b) Es ersetzt ping.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ping ist Diagnose"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ifconfig?', 5, '[{"text": "Schnelle Übersicht", "correct": true, "because": "Netzwerkstatus"}, {"text": "IPv6-Unterstützung", "correct": true, "because": "Zeigt Adressen"}, {"text": "Latenzmessung", "correct": false, "because": "Ping-Aufgabe"}, {"text": "Routing-Konfiguration", "correct": false, "because": "Anderes Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ifconfig unwichtig?', 3, '[{"text": "Scope-ID", "correct": false, "because": "Für Link-Local nötig"}, {"text": "Schnittstellenstatus", "correct": false, "because": "Zeigt Aktivität"}, {"text": "HTTP-Status", "correct": true, "because": "Anwendungsebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Zeigt ifconfig den Standardgateway?', 3, '[{"text": "Nein", "correct": true, "because": "Route-Tool nötig"}, {"text": "Ja", "correct": false, "because": "Nicht Standardausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ifconfig Schnittstellen aktivieren kann?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Parameter up"}, {"text": "Nein", "correct": false, "because": "Funktion vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse zeigt ifconfig für IPv6 standardmäßig?', 4, '[{"text": "Link-Local mit Scope", "correct": true, "because": "FE80::%interface"}, {"text": "Globale Multicast", "correct": false, "because": "Nicht eigener"}, {"text": "Site-lokale Adresse", "correct": false, "because": "Nur bei Konfiguration"}]');
